/**
 * Every label the app shows — one file (docs/GLOSSARY.md, approved 19-10-2026).
 * Components, pages, services and metadata read from `L`; no domain term is hard-coded elsewhere,
 * so a rename is a change to one value here.
 *
 * Casing (GLOSSARY D-1): Title Case for module / page / tab names, record names, buttons, statuses and
 * dropdown values; sentence case for field labels, placeholders, help text, toasts and messages.
 *
 * Sections, in sidebar order: common · nav · roles · customers · leads · opportunities · quotations ·
 * orders · dispatch · installed · service · spares · consumables · field · targets · reports ·
 * dashboard · calendar · admin · catalog.
 */

